&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Valid driver’s license.&lt;/span&gt;&lt;/li&gt;
